begin;
do $tests$
declare sid uuid; aid uuid; actor uuid:=gen_random_uuid(); ctx jsonb; result jsonb; pid uuid; blocked boolean; content jsonb; quote text;
begin
 if has_function_privilege('anon','public.editorial_publication_queue()','EXECUTE') or has_function_privilege('authenticated','public.editorial_publication_plan(text,uuid,uuid,integer,integer,timestamp with time zone,uuid,text)','EXECUTE') then raise exception 'Public plan access allowed'; end if;
 insert into sources(name,url,tier,source_type) values('QA plan source','https://plan-test.invalid/'||actor,'B','local_media') returning id into sid;
 quote:='QA plan fixture '||actor||' Управляющая компания организует ремонт общего имущества.';
 insert into articles(source_id,title,url,body,published_at) values(sid,'QA approved plan article '||actor,'https://plan-test.invalid/'||actor||'/a',repeat(quote||' ',8),'2051-01-01') returning id into aid;
 ctx:=editorial_draft_context(aid);
 content:=jsonb_build_object('title','QA Планируемый черновик','lead','Источник описывает практику организации ремонта.','body',repeat(quote,2),'verification_notes','Проверен первичный источник.','content_kind','practice','facts',jsonb_build_array(jsonb_build_object('claim','Организация ремонта','quote',quote)));
 perform editorial_draft_write(aid,'generate',content,0,ctx->>'source_fingerprint',(ctx->'article'->>'updated_at')::timestamptz,actor,'rusboma@gmail.com');
 blocked:=false; begin perform editorial_publication_plan('schedule',aid,null,1,null,now()+interval '2 days',actor,'rusboma@gmail.com');exception when others then if sqlerrm like 'DRAFT_APPROVAL_REQUIRED%' then blocked:=true;else raise;end if;end;
 if not blocked then raise exception 'Unchecked draft scheduled';end if;
 result:=editorial_draft_write(aid,'approve',null,1,ctx->>'source_fingerprint',(ctx->'article'->>'updated_at')::timestamptz,actor,'rusboma@gmail.com',true);
 blocked:=false; begin perform editorial_publication_plan('schedule',aid,null,2,null,now()-interval '1 hour',actor,'rusboma@gmail.com');exception when others then if sqlerrm like 'INVALID_PLAN_TIME%' then blocked:=true;else raise;end if;end;
 if not blocked then raise exception 'Past time accepted';end if;
 result:=editorial_publication_plan('schedule',aid,null,2,null,now()+interval '2 days',actor,'rusboma@gmail.com');pid:=(result->>'publication_id')::uuid;
 if not exists(select 1 from publications where id=pid and draft_revision=2 and status='approved' and scheduled_at is not null and telegram_message_id is null and published_at is null and body like '%Источник: https://plan-test.invalid/%') then raise exception 'Approved snapshot reservation failed';end if;
 blocked:=false; begin perform editorial_publication_plan('schedule',aid,null,2,null,now()+interval '3 days',actor,'rusboma@gmail.com');exception when others then if sqlerrm like 'DUPLICATE_BLOCKED%' then blocked:=true;else raise;end if;end;
 if not blocked then raise exception 'Repeated schedule allowed';end if;
 perform editorial_publication_plan('reschedule',null,pid,null,1,now()+interval '4 days',actor,'rusboma@gmail.com');
 blocked:=false; begin perform editorial_publication_plan('cancel',null,pid,null,1,null,actor,'rusboma@gmail.com');exception when others then if sqlerrm like 'Conflict%' then blocked:=true;else raise;end if;end;
 if not blocked then raise exception 'Stale plan overwrite allowed';end if;
 blocked:=false; begin perform editorial_console_decide(aid,'reject',actor,'rusboma@gmail.com',(select updated_at from articles where id=aid),'QA cannot change scheduled material');exception when others then if sqlerrm like '%locked%' then blocked:=true;else raise;end if;end;
 if not blocked then raise exception 'Reserved article status changed';end if;
 perform editorial_publication_plan('cancel',null,pid,null,2,null,actor,'rusboma@gmail.com');
 if not exists(select 1 from publications where id=pid and status='rejected' and scheduled_at is null and cancelled_at is not null) then raise exception 'Cancellation failed';end if;
 if not exists(select 1 from jsonb_array_elements(editorial_publication_queue()->'ready') value where value->>'article_id'=aid::text) then raise exception 'Cancelled draft not ready again';end if;
 result:=editorial_publication_plan('schedule',aid,null,2,null,now()+interval '5 days',actor,'rusboma@gmail.com');pid:=(result->>'publication_id')::uuid;
 update articles set body=body||' Source changed with a new observation.' where id=aid;
 blocked:=false; begin perform editorial_publication_plan('reschedule',null,pid,null,1,now()+interval '6 days',actor,'rusboma@gmail.com');exception when others then if sqlerrm like 'Conflict%' then blocked:=true;else raise;end if;end;
 if not blocked then raise exception 'Changed source silently rescheduled';end if;
 perform editorial_publication_plan('cancel',null,pid,null,1,null,actor,'rusboma@gmail.com');
 if exists(select 1 from publications where article_id=aid and (telegram_message_id is not null or published_at is not null)) then raise exception 'Unexpected external publication state';end if;
 update articles set event_date=(now() at time zone 'Europe/Moscow')::date+1 where id=aid;
 update editorial_drafts set content_kind='event_announcement',source_fingerprint=editorial_draft_context(aid)->>'source_fingerprint' where article_id=aid;
 blocked:=false;begin perform editorial_publication_plan('schedule',aid,null,2,null,now()+interval '5 days',actor,'rusboma@gmail.com');exception when others then if sqlerrm like 'EVENT_DATE_PASSED%' then blocked:=true;else raise;end if;end;
 if not blocked then raise exception 'Announcement scheduled after event';end if;
 if (select count(*) from editorial_actions where article_id=aid and action like 'plan_%')<>5 then raise exception 'Plan audit incomplete';end if;
end $tests$;
rollback;
